// TH18 v1.00a st05bs.ecl.txt:64-158 "Boss1" (Stage 5 final boss, non-spell).
// Source t0 = target frame after the 120-frame shell buffer (phase_begin).
// Source interrupt 0: life 3200 / 2400-frame timeout -> BossCard1 (B:67).
const TIME_LIMIT: int = 2522;   // = 120 shell + 2400 source + 2
const SOURCE_LIMIT: int = 2400;
const TH18_BIG_BALL2: int = 656; // source etSprite type19, radius 8.5
const TH18_STAR_R: int = 608;    // source etSprite type16, radius 4

// Source B:129-155, child chain entered at effect record 12:
// WAIT60 -> VELTIME30 (target 0, direction = current) -> VELTIME120
// (target 2 E/N/H, 3 L; direction = aim_player()+U*10deg sampled at entry).
xformdef SUB_TARGET(target: fx) {
    wait(60);
    step_speed(0fx, 30);
    wait(30);
    set_angle(at_effect(aim_player() + (((rand(65536)-32768)*1820/32768) as angle)));
    step_speed(target, 120);
}

// One parent SHOOT: source B:117-118 / B:129-130, mode1 fan, r=-9999994
// (parent's current angle), s=0.7853982 (45deg spacing), speed 0.8 (1 layer).
sub sub_volley(ways: int, target: fx) {
    for i in 0..ways {
        var off: int = (i/2)*8192 + 4096;
        if i%2 != 0 { off = 0-off; }
        _ = fire(TH18_STAR_R, 6, $self_x, $self_y, 0.8fx,
                 $self_angle+(off as angle), SUB_TARGET(target), none);
    }
}

// Parent bullets copy records 0-11: ANIM a1 (retreat, see wave()), INVULN 200
// (bomb-erase protection only), WAIT3, SHOOT+DATA, WAIT3, SHOOT+DATA, GOTO1 (one
// pass), WAIT rank, GOTO1. The record-8 counter is spent after the first pass, so
// the opening volley pairs run back-to-back and later pairs repeat at 6+WAIT gaps.
async sub parent_bullet() {
    var rank: int = global(GVAR_RANK);
    var ways: int = 4;
    var gap: int = 20;
    if rank == 0 { ways = 2; gap = 30; }
    var target: fx = 2fx;
    if rank == 3 { target = 3fx; }
    wait(2); // bullet task first runs at birth+1; first SHOOT is at birth+3
    sub_volley(ways, target);
    wait(3); sub_volley(ways, target);
    wait(3); sub_volley(ways, target);
    wait(3); sub_volley(ways, target);
    loop {
        wait(gap+3);
        sub_volley(ways, target);
        wait(3);
        sub_volley(ways, target);
    }
}

// Source B:99-104: 5-way etAim mode5 ring, etCount(5,1), etSprite(19,3),
// etAngle(90deg,10deg), etSpeed(4,1), etOn. Mode5 = 90deg + half spacing (36deg)
// + 72deg*i, speed 4. ANIM a1 retreats 4*4=16px along each bullet's own angle.
sub wave() {
    sh_reset(0);
    sh_sprite(0, TH18_BIG_BALL2, 3);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, 5, 1);
    sh_angle(0, 126deg, 0deg);
    sh_speed(0, 4fx, 0fx);
    sh_dist(0, -16fx);
    sh_task(0, parent_bullet);
    sh_fire(0);
}

// Source B:88 moveRand(50,0,0.3) under the inherited moveLimit(0,128,280,64):
// x in [-140,140], y in [96,160]; speed 0.3*(1-k/50), mode inherits 0 (linear).
// int slot0 = next-step count, fx0/1 = logical unit vector.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 50 { speed = (50-k) as fx / 50 * 0.3fx; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Source 405b90 = signed unit random * pi; values are unwrapped BAM ints.
    // Direction inner zone is limit centre +-width/height divided by 4: x +-70, y 112..144.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -70fx {
        a = r/3;
    } else if $self_x > 70fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; }
    } else {
        a = r/4;
        var choose: int = rand(65536)%3;
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

async sub pattern() {
    wait(120);
    var until: int = $frame+SOURCE_LIMIT;
    set_self_int(2, until);
    set_self_int(0, 60);
    set_self_fx(0, 0fx);
    set_self_fx(1, 0fx);
    wait(80); // source B:71; first wave at source t=80
    var rank: int = global(GVAR_RANK);
    var gap: int = 200;
    if rank == 2 { gap = 140; }
    if rank == 3 { gap = 100; }
    loop {
        if $frame >= until { return; }
        wave();
        card_wait(gap);   // source B:78-87 (200/200/140/100)
        card_move_rand(); // source B:88 moveRand(50,0,0.3)
        card_wait(60);    // source B:89
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);  // source Boss B:29 setHitbox(48,48) -> 48/2
    set_hurtbox(20fx); // source Boss B:28 setHurtbox(40,40) -> 40/2
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}

// Source S:910 main creates Boss at (0,128); Boss1 inherits that position and the
// inherited moveLimit. The extra controller stays at (0,0) with body collision
// off; the real boss keeps the source hitbox/hurtbox.
async sub controller() {
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_invuln(65535);
    _ = spawn_enemy(0fx, 128fx, 19200, 0, 0, 0, boss_main);
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1, 0, 0, 0, controller);
    loop { wait(600); }
}
